const inp = $('Recibir Datos').first().json;
const cache = $('🔍 Cache Config').first().json;
const empresa = cache.empresa || {};
const waConfig = cache.waConfig || {};
const productos = cache.productos || [];

const leadRaw = $('📋 Buscar Lead').first().json;
const leadsArr = leadRaw?.data || [];
const leadG54 = leadsArr[0] || null;

const leadId = leadG54?.id ? String(leadG54.id) : null;
const esNuevo = !leadId;
const historial = leadG54?.historial || '';
const estado = leadG54?.estado || 'Nuevo';
const nombreGuardado = leadG54?.contact_name || '';
const datosGuardados = leadG54?.datos || {};

const catalogoProductos = productos.map(p => {
  const nombre = p.name || '';
  const desc = p.description || '';
  return nombre ? `${nombre}: ${desc}` : '';
}).filter(l => l.length > 2).join('\n');

const emailVendedor = (empresa.emails || [])[0] || waConfig.WA_Email_Vendedor || 'risosadmi@gmail.com';
const followup24 = waConfig.WA_FollowUp_24h || '';
const followup72 = waConfig.WA_FollowUp_72h || '';

const kbRaw = $('📚 Buscar KB').first().json;
const kbRecords = kbRaw?.records || [];
const msgTexto = (inp.texto || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'');

let kbContexto = '';
if (kbRecords.length > 0) {
  const scored = kbRecords.map(r => {
    const f = r.fields || {};
    const kwField = f['keywords'] || f['fld0yfZZ92Sn4azoR'] || '';
    const kws = kwField.toLowerCase().split(/[,\s]+/);
    const score = kws.filter(kw => kw.length > 2 && msgTexto.includes(kw)).length;
    const pregunta = f['fldoHtlrUwmkCCKwM'] || Object.values(f)[0] || '';
    const corta = f['fldmfEyHk7i3o24T5'] || f['respuesta_corta'] || '';
    return { score, pregunta, corta };
  }).filter(r => r.score > 0).sort((a,b) => b.score - a.score).slice(0,3);
  if (scored.length > 0) {
    kbContexto = '\n\nINFORMACIÓN VERIFICADA (usa SOLO estos datos):\n' +
      scored.map(r => `• ${r.pregunta}\n  → ${r.corta}`).join('\n');
  }
}

return [{json: {
  telefono: inp.telefono,
  texto: inp.texto,
  nombreContacto: inp.nombreContacto || nombreGuardado,
  leadId, estado, historial, esNuevo,
  datosRecolectados: datosGuardados,
  emailVendedor, followup24, followup72,
  catalogoProductos, kbContexto,
  empresa, waConfig, productos
}}];

const staticData = $getWorkflowStaticData('global');
const now = Date.now();
const CACHE_TTL = 3600000;
const AT_TOKEN = 'Bearer AT_TOKEN_HIDDEN';
const G54 = 'https://apigrowth.mdarthurdigital.com';
const inp = $input.first().json;

let empresa = {};
let waConfig = {};
let productos = [];

if (staticData.empresa && (now - (staticData.configCachedAt || 0)) < CACHE_TTL) {
  empresa = staticData.empresa;
  waConfig = staticData.waConfig;
  productos = staticData.productos || [];
} else {
  try {
    const r1 = await $helpers.httpRequest({ method: 'GET', url: `${G54}/api/n8n/companies/1`, headers: { Authorization: 'Bearer ' } });
    empresa = r1.data || r1 || {};
  } catch(e) { empresa = staticData.empresa || {}; }

  try {
    const r2 = await $helpers.httpRequest({ method: 'GET', url: `${G54}/api/n8n/companies/1/productos-servicios`, headers: { Authorization: 'Bearer ' } });
    productos = r2.data || [];
  } catch(e) { productos = staticData.productos || []; }

  try {
    const r3 = await $helpers.httpRequest({ method: 'GET', url: 'https://api.airtable.com/v0/appUOYi54iBfaDcLn/tblj4radGXHN7HBJi?maxRecords=1', headers: { Authorization: AT_TOKEN } });
    waConfig = r3.records?.[0]?.fields || {};
  } catch(e) { waConfig = staticData.waConfig || {}; }

  staticData.empresa = empresa;
  staticData.productos = productos;
  staticData.waConfig = waConfig;
  staticData.configCachedAt = now;
}

return [{ json: { ...inp, empresa, waConfig, productos } }];
